// peerReplyKind marks a message generated by this responder.
//
// It is what stops two idle agents talking forever: a reply never triggers
// another reply. Agents can still start a thread themselves mid-task with
// message_peer, and a human can always say something new.
const peerReplyKind = "reply"

// peerSummaryKind marks a compaction summary. It stands in for messages rather
// than being one, so nobody answers it.
const peerSummaryKind = "summary"

// peerSystemKind marks a note the platform itself wrote into a channel — the
// record of a slash command, a bot coming up. Agents never answer it.
const peerSystemKind = "system"

// RunPeerResponder lets idle agents answer messages addressed to them.
//
// The agent loop only reads its inbox while a task is running (peerContext is
// built per turn), so an instance sitting idle never saw a broadcast and never
// answered one — which reads, correctly, as "nobody responded". This closes
// that gap: an idle instance still belongs to the fleet and should reply when
// spoken to.
//
// Instances that are mid-task are skipped on purpose. They will see the message
// in their next turn's FLEET block with the full context of what they are
// doing, which is a better answer than one composed out of band.
func (s *Server) RunPeerResponder(ctx context.Context) {
	const interval = 15 * time.Second

	// Last message answered per instance, so a reply is generated once. Held
	// in memory deliberately: on restart every instance re-reads its recent
	// inbox, and answering a stale message twice is cheaper than tracking
	// acknowledgements in the database.
	var mu sync.Mutex
	seen := map[string]time.Time{}

	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			instances, err := s.db.ListInstances(ctx)
			if err != nil {
				continue
			}
			// Whoever the message names answers first, in the order named.
			// Replies are generated one at a time, so the order is also the
			// order parts get claimed -- which is what lets a later agent see
			// what an earlier one already took. The pending message is the
			// same for everyone, so any unanswered one gives the ordering.
			if pending, ok := s.anyPending(ctx, instances); ok {
				instances = orderByMention(pending.Content, instances)
			}
			for i := range instances {
				inst := instances[i]
				if inst.State != protocol.InstanceRunning {
					continue
				}
				if s.instanceIsBusy(ctx, inst.ID) {
					continue
				}

				mu.Lock()
				since := seen[inst.ID]
				mu.Unlock()

				msg, ok := s.nextUnanswered(ctx, inst.ID, since)
				if !ok {
					continue
				}

				mu.Lock()
				seen[inst.ID] = msg.CreatedAt
				mu.Unlock()

				s.replyToPeer(ctx, inst, msg)
			}
		}
	}
}

// instanceIsBusy reports whether a task is mid-flight on this instance. A busy
// agent is left alone: it will read the message in its next turn, with the
// context of what it is actually doing.
func (s *Server) instanceIsBusy(ctx context.Context, instanceID string) bool {
	tasks, err := s.db.ListTasks(ctx, instanceID, 20)
	if err != nil {
		// Unknown means leave it alone, rather than risk talking over a run.
		return true
	}
	for _, t := range tasks {
		switch t.State {
		case protocol.TaskRunning, protocol.TaskQueued, protocol.TaskAwaitingHuman:
			return true
		}
	}
	return false
}

// nextUnanswered finds the newest message this instance should answer.
//
// Only one per tick: answering a backlog all at once would flood the thread,
// and the newest message is the one worth responding to.
func (s *Server) nextUnanswered(ctx context.Context, instanceID string, since time.Time) (protocol.PeerMessage, bool) {
	msgs := vault.GlobalBus.ListMessages(ctx, instanceID, 10)

	// An agent's own most recent reply is a high-water mark that survives a
	// restart, unlike the in-memory one: having already replied after a
	// message is proof of having answered it. Without this every deploy made
	// the whole fleet answer the same question again, which is visible in any
	// channel that has been through a few.
	for _, m := range msgs {
		if m.FromInstanceID == instanceID && m.Kind == peerReplyKind &&
			m.CreatedAt.After(since) {
			since = m.CreatedAt
		}
	}

	var best protocol.PeerMessage
	found := false
	// Anything older than this is not worth answering. The high-water mark is
	// in memory, so every restart used to look like a fleet with a full inbox:
	// each agent answered the newest message again, however many hours old,
	// and a channel with three agents gained three replies to a question that
	// had been answered that morning. Verified against the live fleet, where
	// the last operator message was at 07:40 and the agents were still
	// re-answering it at 16:03.
	const freshEnough = 10 * time.Minute
	cutoff := time.Now().Add(-freshEnough)

	for _, m := range msgs {
		switch {
		case m.FromInstanceID == instanceID: // never answer yourself
		case !s.mayAnswer(instanceID, m):
			// Not in that room. A message the operator writes into a thread
			// between two other agents is addressed to the fleet, because a
			// message carries one recipient and a thread has several — so it
			// lands in every inbox. Without this check a third agent answered
			// into a pair thread it was not part of, which is exactly what a
			// private thread is supposed to prevent.
		case m.Kind == peerReplyKind: // replies do not beget replies
		case m.Kind == peerSummaryKind:
			// A summary is a record of what was said, not something said to
			// anyone. Compacting a thread used to make every agent chime in.
		case m.Kind == peerSystemKind:
			// A command result the console posted into the channel. Nobody
			// asked the fleet anything; answering it is noise.
		case m.CreatedAt.Before(cutoff):
		case !m.CreatedAt.After(since):
		case found && !m.CreatedAt.After(best.CreatedAt):
		default:
			best, found = m, true
		}
	}
	return best, found
}

func (s *Server) replyToPeer(ctx context.Context, inst protocol.Instance, msg protocol.PeerMessage) {
	ctx, cancel := context.WithTimeout(ctx, s.cfg.FleetReplyTimeout)
	defer cancel()

	scope := "you directly"
	if msg.ToInstanceID == "broadcast" {
		scope = "the whole fleet"
	}

	// "What is everyone up to" is the question this feature exists to answer,
	// and it cannot be answered from the message alone. Give the agent its own
	// recent history so the reply is a real status report rather than a
	// paraphrase of the question.
	status := s.recentActivity(ctx, inst)

	// What colleagues have already claimed, and who else is in the fleet.
	//
	// Without this every agent answers in isolation: told to work together on
	// something, four of them each replied "I will take the lead on building
	// it" within eighty seconds and four identical whole-game builds started.
	// The instruction not to duplicate a colleague was useless because nobody
	// could see a colleague. They reply over a minute or so, so a later one
	// can genuinely read what an earlier one took -- it just had to be put in
	// front of it.
	claimed := s.claimsSoFar(ctx, inst, msg)
	roster := s.fleetRoster(ctx, inst)
	assigned := s.assignedPart(ctx, inst, msg)
	// An agent the operator did not name will not be started, so it should not
	// announce a part it is never going to do. Told only that colleagues had
	// claimed things, one still replied "I will build the single-file HTML
	// page" for a job addressed to somebody else.
	bystander := ""
	if s.namedSomeoneElse(ctx, inst, msg) {
		bystander = "\nThe operator named other agents for this and did not name " +
			"you. It is not your job. Say in one sentence that you are standing " +
			"by, and do not claim a part or describe what you would build.\n\n"
	}

	// Two different things get said in fleet comms, and answering both as a
	// status update was wrong.
	//
	// This was built to answer "what is everyone up to", so the prompt told
	// the agent to reply with a status update and never to claim it had
	// started anything. That is right for a question and useless for a
	// request: asked to work together and build something, four agents each
	// replied "I am currently idle and available" and nobody did anything.
	// The instruction not to claim work made it structurally incapable of
	// agreeing to any.
	//
	// So the agent decides which it was given, and says so in the first word.
	// A deterministic marker rather than a second classifier call: the reply
	// has to be generated anyway, and a round trip per agent per broadcast to
	// label it would cost more than the answer.
	resp, err := s.models.CompleteRole(ctx, inst.ProviderIDs, protocol.RoleChat,
		connectors.Request{
			System: "You are the agent \"" + inst.Name + "\" in a fleet of autonomous " +
				"desktop agents, reporting to your operator. " + scope +
				" was messaged.\n\n" + status + "\n\n" +
				roster + claimed + assigned + bystander +
				"Decide first what you were sent.\n\n" +
				"If it ASKS YOU TO DO SOMETHING -- build, make, write, fix, find " +
				"out, work together on something -- reply starting with the single " +
				"word PLAN: followed by the specific part YOU will take on, in one " +
				"or two sentences. Say what you will actually produce. Do not ask " +
				"for permission and do not ask which part to take -- decide.\n\n" +
				"Answer as yourself, " + inst.Name + ", in the first person. Do not " +
				"say you will take another agent's role or act as them -- they are " +
				"answering for themselves.\n\n" +
				"Dividing the work is the point. If a colleague above has already " +
				"claimed a part, you may NOT take that part or restate it in other " +
				"words -- pick something the work still needs and nobody has. If " +
				"someone is already writing the thing itself, take the design, the " +
				"assets, the test pass, the review, or a component they will need " +
				"and can drop in. Only one agent writes the main artefact. If every " +
				"obvious part is taken, say what you will do to support whoever has " +
				"the hardest one, and be specific about it.\n\n" +
				"Otherwise it is a QUESTION about you or your machine. Reply in one " +
				"or two short sentences, in the first person, as a status update. " +
				"Ground every claim in the history above: if it says you have run " +
				"nothing, say you are idle and available. Never invent work, never " +
				"claim to have started something, and do not list your capabilities " +
				"unless you were asked what you can do.",
			Messages: s.peerQuestionMessages(ctx, inst, msg),
			// A reasoning model would spend the whole budget thinking and
			// return nothing.
			DisableThinking: true,
			MaxTokens:       260,
			Temperature:     0.3,
		})
	if err != nil {
		s.log.Warn("peer reply failed", "instance", inst.ID, "err", err)
		return
	}
	body := strings.TrimSpace(resp.Text)
	if body == "" {
		return
	}

	// Where the reply goes.
	//
	// An operator broadcast is answered in the group so every reply sits under
	// the question. Anything else — an agent asking another agent something —
	// is answered directly to the asker, which keeps agent chatter in its own
	// thread instead of filling the fleet channel with conversations the
	// operator did not start. The direct threads are still visible; they are
	// just not mixed in.
	to := msg.FromInstanceID
	if isOperator(msg) {
		// The operator has no instance ID for a reply to be addressed to. In a
		// two-agent thread the answer goes to the other agent, which is what
		// lets the pair carry on talking; anywhere else it goes to the fleet.
		if other, ok := vault.GlobalBus.OtherAgentMember(msg.ConversationID, inst.ID); ok {
			to = other
		} else {
			to = "broadcast"
		}
	}
	if to == "" {
		to = "broadcast"
	}

	// Which thread the answer belongs in is a separate question from who it is
	// addressed to, and conflating them leaked replies. An operator question in
	// a pair thread has no instance to address, so `to` falls back to
	// broadcast -- that must not drag the answer out of the thread it was
	// asked in and into the fleet channel.
	conv := msg.ConversationID
	if conv == "" {
		conv = protocol.BroadcastConversationID
	}
	vault.GlobalBus.SendMessageIn(ctx, conv, inst.ID, inst.Name, to, peerReplyKind, body, nil)
	s.log.Info("agent answered a peer message", "instance", inst.Name, "to", to, "conversation", conv)

	// A plan that nobody acts on is the bug this is fixing. If the agent
	// committed to a part, start it working on that part.
	if plan, ok := planFrom(body); ok && isOperator(msg) {
		s.startFromPlan(ctx, inst, msg, plan)
		return
	}
	// A colleague's request, inside a live job, is also work. Handed
	// Builder's build, Checker asked Builder three times to publish the
	// files; Builder answered "PLAN: I will publish them" three times and
	// did nothing, because a plan given to a peer never started anything.
	// That rule is right between idle bots -- one bot's question must not be
	// another bot's afternoon -- and wrong when the asker is mid-task on a job
	// both are part of. The job's round limit bounds the ping-pong.
	if plan, ok := planFrom(body); ok && !isOperator(msg) {
		s.startFromPeerRequest(ctx, inst, msg, plan)
		return
	}
	// An agent that said it would wait — "ready to review once Builder is
	// done" — is still part of the job. Register it so the relay can hand it
	// the work when there is work.
	if isOperator(msg) {
		s.waitForHandoff(ctx, inst, msg)
	}
}

// planMarker is how an agent says it was asked to do something rather than
// asked a question.
const planMarker = "PLAN:"

// planFrom pulls the committed part out of a reply, if there is one.
//
// Only when the agent opened with the marker. Matching "plan" anywhere in a
// sentence would turn "I have no plans today" into a task.
func planFrom(body string) (string, bool) {
	trimmed := strings.TrimSpace(body)
	if trimmed == "" {
		return "", false
	}

	// The marker at the start of the reply, or of any later sentence or line:
	// "I'm idle. PLAN: I'll take the code" is a plan that happens to open
	// with a status report.
	if i := planMarkerIndex(trimmed); i >= 0 {
		if plan := strings.TrimSpace(trimmed[i+len(planMarker):]); plan != "" {
			return plan, true
		}
		return "", false
	}

	// A commitment without the marker still counts.
	//
	// Asked to divide up a job, two agents replied "I accept the task of
	// writing the game itself" and "I will take the design phase" -- plainly
	// taking a part, and neither started work, because neither had opened with
	// the word the parser wanted. The marker is what the prompt asks for; this
	// is what the models actually do about half the time, and refusing to read
	// it made the two most important parts of a job silently not happen.
	if commitsToWork(trimmed) {
		return trimmed, true
	}
	return "", false
}

// commitsToWork reports whether a reply is an agent taking something on rather
// than reporting its state.
//
// Deliberately narrow. The failure that matters is the other direction: a
// status update read as a commitment starts a task nobody asked for, on an
// agent that just said it was idle.
func commitsToWork(body string) bool {
	// Sentence by sentence. The first version read only the first sentence,
	// and Builder's "I'm idle and available -- nothing has actually run yet.
	// I'll take the code: read the existing files, then rebuild the app" was
	// filed as a status report. The builder then waited to be handed its own
	// work, and the job stalled. A status sentence vetoes itself, not the
	// commitment that follows it.
	for _, sentence := range strings.FieldsFunc(body, func(r rune) bool {
		return r == '.' || r == '\n' || r == '!' || r == '?'
	}) {
		lower := strings.ToLower(strings.TrimSpace(sentence))
		idle := false
		for _, word := range []string{"idle", "available", "no tasks", "nothing to report",
			"awaiting", "standing by", "ready to receive", "ready for"} {
			if strings.Contains(lower, word) {
				idle = true
				break
			}
		}
		if idle {
			continue
		}
		for _, opener := range []string{
			"i will ", "i'll ", "i am taking ", "i'm taking ",
			"i accept ", "i have taken ", "i will take", "i shall ",
			"my part ", "i can take ", "i'm going to ", "i am going to ",
		} {
			if strings.HasPrefix(lower, opener) {
				return true
			}
		}
	}
	return false
}

// planMarkerIndex finds "PLAN:" where a sentence or line starts, or -1.
func planMarkerIndex(body string) int {
	upper := strings.ToUpper(body)
	from := 0
	for {
		i := strings.Index(upper[from:], planMarker)
		if i < 0 {
			return -1
		}
		i += from
		before := strings.TrimRight(upper[:i], " \t*")
		if before == "" || strings.ContainsRune(".!?\n:—-", rune(before[len(before)-1])) {
			return i
		}
		from = i + len(planMarker)
	}
}

// waitForHandoff registers an agent that has a part but nothing to do yet.
//
// Two cases land here. One is an agent that said in so many words that it is
// waiting — "ready to review once Builder is done" — which is the correct
// answer and used to mean it was simply forgotten. The other is an agent whose
// part is testing or reviewing: starting that immediately tests nothing and,
// worse, leaves it busy when the builder finally publishes.
func (s *Server) waitForHandoff(ctx context.Context, inst protocol.Instance, msg protocol.PeerMessage) {
	instances, err := s.db.ListInstances(ctx)
	if err != nil {
		return
	}
	part := assignmentFor(msg.Content, inst.Name, instances)
	if part == "" {
		return // nobody named it; it is not on this job
	}
	stage := stageOf(part)
	if stage == stageUnknown {
		return
	}
	// A producer named by the operator is not waiting for anything: nothing
	// upstream of a builder will ever hand it work. Whatever it said in its
	// reply -- "standing by", a plan the parser did not read -- the operator
	// assigned it a part that makes something, so it starts on that part.
	if !stage.waitsForWork() && !defersToColleague(part) {
		s.log.Info("named to produce; starting on the assigned part rather than waiting",
			"instance", inst.Name, "stage", stage.String())
		s.startFromPlan(ctx, inst, msg, part)
		return
	}
	conv := msg.ConversationID
	if conv == "" {
		conv = vault.GlobalBus.DefaultChannel()
	}
	// A new request supersedes the last one here too.
	//
	// This was only done when an agent started work, so a broadcast that
	// produced nothing but waiting agents -- everyone named for testing and
	// reviewing, say -- left its job behind for good. Over a long-running
	// deployment those accumulate, one per such request, and nothing ever
	// removes them.
	s.relay.forgetOthers(msg.Content)
	s.relay.waitFor(msg.Content, conv, collaborator{
		InstanceID: inst.ID,
		Name:       inst.Name,
		Plan:       part,
		Stage:      stage,
	})
	s.log.Info("agent is waiting to be handed work",
		"instance", inst.Name, "stage", stage.String())
}

// startFromPeerRequest starts the work an agent just promised a colleague,
// when that colleague is mid-task on a job and this agent is idle.
func (s *Server) startFromPeerRequest(ctx context.Context, inst protocol.Instance, msg protocol.PeerMessage, plan string) {
	if inst.State != protocol.InstanceRunning || msg.FromInstanceID == "" {
		return
	}
	job, asker, ok := s.relay.jobOfInstance(msg.FromInstanceID)
	if !ok {
		return
	}
	// Only for bots on the job: a member, or named in the request. Checker
	// asked gui-scout something in passing and gui-scout, a bystander with
	// no part, started a task on the strength of its own polite "I will".
	if !onJob(job, inst) {
		s.log.Info("not starting peer-requested work; not on this job",
			"instance", inst.Name, "asker", asker.Name)
		return
	}
	if s.instanceIsBusy(ctx, inst.ID) {
		return
	}
	task := &protocol.Task{
		ID:         store.NewID(),
		InstanceID: inst.ID,
		Goal: fmt.Sprintf("%s, who is working on the fleet request below, asked you:\n%s\n\n"+
			"You answered: %s\n\nDo that now, on your own machine. When it is done, publish "+
			"what you produced with publish_work under a stable name and tell %s with "+
			"message_peer exactly where it is: the catalog name, or the address of anything "+
			"you are serving (your machine is http://%s:<port> to colleagues). "+
			"Do not use ask_human; decide the small things yourself.\n\n"+
			"The fleet request: %s",
			asker.Name, clipLine(msg.Content, 800), clipLine(plan, 600), asker.Name,
			sandboxHost(inst.ID), job.Request),
		State:     protocol.TaskQueued,
		MaxSteps:  s.cfg.MaxSteps,
		CreatedAt: time.Now().UTC(),
		Params:    map[string]string{protocol.ParamHandoff: "1"},
	}
	me := collaborator{InstanceID: inst.ID, Name: inst.Name, Plan: plan, Stage: stageOf(plan)}
	if !s.relay.claimRound(job, task.ID, me, msg.FromInstanceID) {
		s.log.Info("not starting peer-requested work; the job is out of rounds",
			"instance", inst.Name, "asker", asker.Name)
		return
	}
	bg := context.WithoutCancel(ctx)
	if err := s.db.CreateTask(bg, task); err != nil {
		s.log.Warn("could not queue peer-requested work", "instance", inst.Name, "err", err)
		return
	}
	if err := s.runner.Start(bg, task); err != nil {
		s.log.Warn("could not start peer-requested work", "instance", inst.Name, "err", err)
		return
	}
	s.log.Info("agent started work a colleague asked for",
		"instance", inst.Name, "asker", asker.Name, "task", task.ID, "round", job.Round)
}

// onJob reports whether a bot has a part on a job: registered as a member, or
// named in the request that opened it.
func onJob(job *collaboration, inst protocol.Instance) bool {
	for _, m := range job.Members {
		if m.InstanceID == inst.ID {
			return true
		}
	}
	_, _, named := mentionSpan(job.Request, inst.Name)
	return named
}

// startFromPlan turns an agent's stated part into a task it actually runs.
//
// Only for an operator's message: agents talking among themselves must not be
// able to start work on each other, or one bot's question becomes another
// bot's afternoon. And only when the agent is idle -- a broadcast arriving
// mid-task should not derail what it was already asked to do.
func (s *Server) startFromPlan(ctx context.Context, inst protocol.Instance, msg protocol.PeerMessage, plan string) {
	if inst.State != protocol.InstanceRunning {
		return
	}
	// Naming people is also saying who is not needed.
	//
	// "Auditor write a two-sentence note" asked one agent for one small thing,
	// and two others started writing their own version of the same note. An
	// agent shown a colleague's claim sometimes declines and sometimes does
	// not; whether it does should not decide whether the fleet does the work
	// three times. If anybody was named, only the named work.
	if s.namedSomeoneElse(ctx, inst, msg) {
		s.log.Info("not starting work; the operator named someone else",
			"instance", inst.Name)
		return
	}
	// Testing and reviewing wait for something to exist. Starting them now
	// produces a test of nothing and, worse, an agent that is busy when the
	// builder finally publishes -- which is why every handoff was skipped.
	//
	// Unless this agent is the one named first.
	//
	// "ToolCheck open the rollr app from the catalog and test it, Builder fix
	// what ToolCheck finds" names a tester first and points at work that
	// already exists. Waiting for a build nobody asked for meant the request
	// never happened at all. Asking instead whether anyone was named to
	// produce was worse: "fix what ToolCheck reports" does not read as a build,
	// so both started at once and the builder set about fixing a report that
	// did not exist yet.
	//
	// Mention order already decides who goes first, and it answers this too.
	// Whoever was named first starts -- what they need is either in the
	// catalog or was never coming -- and everyone named after them waits to be
	// handed it, which is the order the operator wrote down.
	if stage := s.stageForAgent(ctx, inst, msg, plan); stage.waitsForWork() || s.partDefers(ctx, inst, msg, plan) {
		if !s.namedFirst(ctx, inst, msg) {
			s.waitForHandoff(ctx, inst, msg)
			return
		}
		s.log.Info("starting downstream work; named first, so nothing is coming to it",
			"instance", inst.Name)
	}
	// One driver at a time, the same rule the task endpoint enforces: a
	// broadcast arriving mid-task must not derail what the agent was already
	// asked to do.
	existing, err := s.db.ListTasks(ctx, inst.ID, 20)
	if err != nil {
		return
	}
	for _, t := range existing {
		if t.State == protocol.TaskRunning || t.State == protocol.TaskAwaitingHuman ||
			t.State == protocol.TaskQueued {
			return
		}
	}

	task := &protocol.Task{
		ID:         store.NewID(),
		InstanceID: inst.ID,
		OwnerID:    msg.FromUserID,
		// Both halves: the request gives the goal its context, the plan is
		// what this particular agent said it would contribute.
		Goal: "The operator asked the fleet: " + msg.Content +
			"\n\nYour part, which you chose: " + plan +
			"\n\nDo that part. " + catalogGuidance +
			" Publish what you produce to the shared work catalog with " +
			"publish_work so the rest of the fleet can build on it. Message a " +
			"peer if you need something from them.\n\n" +
			// The operator broadcast this and walked away. An agent that stops
			// to ask them something waits eight minutes for a reply that is
			// not coming, and everyone waiting on its part waits with it.
			// Bots are on separate machines. Builder built on its own disk and
			// never published; Checker, handed the work, searched its own disk.
			"Every bot has its own machine. Your files are on yours only; a colleague " +
			"cannot see them unless you publish_work them or serve them -- your machine " +
			"is reachable to colleagues as http://" + sandboxHost(inst.ID) + ":<port>, so " +
			"if you run a web server, say that address and port in your report.\n\n" +
			"This was asked of the fleet, not of you in a conversation: nobody " +
			"is sitting there waiting to answer questions about it. Do not use " +
			"ask_human -- decide the small things yourself and say what you " +
			"decided when you publish. Ask a colleague with message_peer if you " +
			"need something only they have.",
		State:     protocol.TaskQueued,
		MaxSteps:  s.cfg.MaxSteps,
		CreatedAt: time.Now().UTC(),
	}
	// Detached from the request that triggered it: the operator's message has
	// long been answered, and a task must not die with its HTTP context.
	bg := context.WithoutCancel(ctx)
	if err := s.db.CreateTask(bg, task); err != nil {
		s.log.Warn("could not queue work from a fleet plan", "instance", inst.Name, "err", err)
		return
	}
	if err := s.runner.Start(bg, task); err != nil {
		s.log.Warn("could not start work from a fleet plan", "instance", inst.Name, "err", err)
		return
	}
	// A new request supersedes the last one. Without this an agent publishing
	// for today's job hands work on for yesterday's, because the relay still
	// remembers who was doing what then.
	s.relay.forgetOthers(msg.Content)

	// Record who is doing what, so finishing this part can wake whoever the
	// next one belongs to. Without it an agent finishes, publishes, and stops,
	// and the colleague who would review it never hears.
	conv := msg.ConversationID
	if conv == "" {
		conv = vault.GlobalBus.DefaultChannel()
	}
	// The stage comes from what the operator assigned where there is an
	// assignment, and from the agent's own words otherwise. An agent told to
	// test that describes its part as "define the game logic" is still the
	// tester, and classifying it as a designer left the relay with four
	// designers and nowhere to send the work.
	stage := s.stageForAgent(ctx, inst, msg, plan)
	s.relay.join(task.ID, msg.Content, conv, collaborator{
		InstanceID: inst.ID,
		Name:       inst.Name,
		Plan:       plan,
		Stage:      stage,
	})
	s.log.Info("agent started work from a fleet request",
		"instance", inst.Name, "task", task.ID, "plan", clipLine(plan, 80))
}

func clipLine(s string, n int) string {
	s = strings.Join(strings.Fields(s), " ")
	if len(s) <= n {
		return s
	}
	return s[:n] + "..."
}

// mayAnswer reports whether this agent belongs in the message's thread.
//
// The broadcast channel and unfiled messages are open to everyone; a named
// conversation is not.
func (s *Server) mayAnswer(instanceID string, m protocol.PeerMessage) bool {
	conv := m.ConversationID
	if conv == "" || conv == protocol.BroadcastConversationID {
		return true
	}
	// A message addressed to this agent is for it whatever thread it sits in.
	if m.ToInstanceID == instanceID {
		return true
	}
	return vault.GlobalBus.IsMember(conv, instanceID)
}

// isOperator reports whether a message came from a human rather than an agent.
// Operator messages have no originating instance.
func isOperator(m protocol.PeerMessage) bool {
	return strings.TrimSpace(m.FromInstanceID) == ""
}

// recentActivity summarises what this agent has actually been doing, so a
// status reply is grounded in the record rather than improvised.
func (s *Server) recentActivity(ctx context.Context, inst protocol.Instance) string {
	tasks, err := s.db.ListTasks(ctx, inst.ID, 5)
	if err != nil || len(tasks) == 0 {
		return "YOUR HISTORY\nYou have not been given any work yet. You are idle and available."
	}

	var sb strings.Builder
	sb.WriteString("YOUR HISTORY (most recent first)\n")
	for i, t := range tasks {
		if i >= 3 {
			break
		}
		line := "- " + string(t.State) + ": " + trunc(t.Goal, 120)
		switch {
		case t.Result != "":
			line += " — outcome: " + trunc(t.Result, 160)
		case t.Error != "":
			line += " — failed: " + trunc(t.Error, 160)
		}
		sb.WriteString(line + "\n")
	}
	running := false
	for _, t := range tasks {
		if t.State == protocol.TaskRunning || t.State == protocol.TaskQueued {
			running = true
			break
		}
	}
	if running {
		sb.WriteString("Something of yours is still in flight.")
	} else {
		sb.WriteString("Nothing is running right now; you are free.")
	}
	return sb.String()
}

func trunc(s string, n int) string {
	s = strings.TrimSpace(s)
	if len(s) <= n {
		return s
	}
	return s[:n] + "..."
}

// claimsSoFar lists the parts colleagues have already taken on this request.
//
// The reason four agents all built the same game: each was asked in isolation,
// so "do not duplicate a colleague" was advice about people it could not see.
// Replies land over a minute or so, so whoever answers later can read what was
// already claimed — provided somebody shows them.
func (s *Server) claimsSoFar(ctx context.Context, inst protocol.Instance, msg protocol.PeerMessage) string {
	conv := msg.ConversationID
	if conv == "" {
		conv = vault.GlobalBus.DefaultChannel()
	}

	var claims []string
	for _, m := range vault.GlobalBus.ListConversationMessages(ctx, conv, 40) {
		// Only replies to this request, and only from someone else.
		if !m.CreatedAt.After(msg.CreatedAt) || m.FromInstanceID == inst.ID {
			continue
		}
		plan, ok := planFrom(m.Content)
		if !ok {
			continue
		}
		claims = append(claims, "- "+m.FromInstanceName+" has taken: "+clipLine(plan, 240))
	}
	if len(claims) == 0 {
		return "\nNobody has claimed a part yet. You are first to answer, so take " +
			"the part that most needs doing.\n\n"
	}
	return "\nAlready claimed by your colleagues — do not take any of these:\n" +
		strings.Join(claims, "\n") + "\n\n"
}

// fleetRoster names the other agents and what each is for, so a part can be
// left to whoever it suits rather than taken by whoever answers first.
func (s *Server) fleetRoster(ctx context.Context, inst protocol.Instance) string {
	instances, err := s.db.ListInstances(ctx)
	if err != nil || len(instances) < 2 {
		return ""
	}
	var lines []string
	for _, other := range instances {
		if other.ID == inst.ID || other.State != protocol.InstanceRunning {
			continue
		}
		role := other.ArchetypeID
		if t := protocol.BotTemplateByID(other.ArchetypeID); t != nil {
			role = t.Name
		}
		if role == "" {
			role = "general purpose"
		}
		lines = append(lines, "- "+other.Name+" ("+role+")")
	}
	if len(lines) == 0 {
		return ""
	}
	return "\nOther agents are working on this alongside you. They will answer " +
		"for themselves -- you are not any of them, and must never reply as " +
		"though you were:\n" + strings.Join(lines, "\n") + "\n"
}

// anyPending returns an unanswered message for any agent, to decide the order
// they answer in.
//
// The ordering has to be settled before the first reply is generated, and the
// message is the same for all of them, so the first one found will do.
func (s *Server) anyPending(ctx context.Context, instances []protocol.Instance) (protocol.PeerMessage, bool) {
	for _, in := range instances {
		if in.State != protocol.InstanceRunning {
			continue
		}
		if msg, ok := s.nextUnanswered(ctx, in.ID, time.Time{}); ok {
			return msg, true
		}
	}
	return protocol.PeerMessage{}, false
}

// assignedPart is what the message asked this agent, specifically, to do.
//
// Given the whole message and nothing else, two agents named for testing and
// reviewing both wrote the design instead -- word-for-word the same design --
// and the parts they had been named for went undone. The instruction was in
// the message; it just was not addressed to anybody.
func (s *Server) assignedPart(ctx context.Context, inst protocol.Instance, msg protocol.PeerMessage) string {
	instances, err := s.db.ListInstances(ctx)
	if err != nil {
		return ""
	}
	part := assignmentFor(msg.Content, inst.Name, instances)
	if part == "" {
		return ""
	}
	return "\nThe operator named you specifically and asked you to: " + part +
		"\nThat is your part. Do that, not somebody else's.\n\n"
}

// stageForAgent decides what part of the work an agent is doing.
//
// What the operator assigned wins over the agent's own paraphrase of it: an
// agent told to test that describes its part as "define the game logic" is
// still the tester, and taking it at its word left the relay with four
// designers and nowhere to send anything.
func (s *Server) stageForAgent(ctx context.Context, inst protocol.Instance, msg protocol.PeerMessage, plan string) relayStage {
	if instances, err := s.db.ListInstances(ctx); err == nil {
		if part := assignmentFor(msg.Content, inst.Name, instances); part != "" {
			if assigned := stageOf(part); assigned != stageUnknown {
				return assigned
			}
		}
	}
	return stageOf(plan)
}

// partDefers reports whether the operator's assignment for this agent, or
// failing that its own plan, says it waits on a colleague's output.
func (s *Server) partDefers(ctx context.Context, inst protocol.Instance, msg protocol.PeerMessage, plan string) bool {
	if instances, err := s.db.ListInstances(ctx); err == nil {
		if part := assignmentFor(msg.Content, inst.Name, instances); part != "" {
			return defersToColleague(part)
		}
	}
	return defersToColleague(plan)
}

// namedSomeoneElse reports whether the message named agents and this is not
// one of them.
//
// A message that names nobody is addressed to whoever can help, and everybody
// may take a part.
func (s *Server) namedSomeoneElse(ctx context.Context, inst protocol.Instance, msg protocol.PeerMessage) bool {
	instances, err := s.db.ListInstances(ctx)
	if err != nil {
		return false // unknown: do not silence the fleet on a database blip
	}
	anyNamed := false
	for _, other := range instances {
		if _, _, ok := mentionSpan(msg.Content, other.Name); ok {
			if other.ID == inst.ID {
				return false // named: this is its job
			}
			anyNamed = true
		}
	}
	return anyNamed
}

// namedFirst reports whether this agent is the earliest one the message names.
//
// The first one named has nobody ahead of it to be handed work by, so if it is
// waiting it is waiting for something that will never arrive.
func (s *Server) namedFirst(ctx context.Context, inst protocol.Instance, msg protocol.PeerMessage) bool {
	instances, err := s.db.ListInstances(ctx)
	if err != nil {
		return false // unknown: keep the cautious behaviour and wait
	}
	mine := mentionIndex(msg.Content, inst.Name)
	if mine < 0 {
		return false
	}
	for _, other := range instances {
		if other.ID == inst.ID {
			continue
		}
		if at := mentionIndex(msg.Content, other.Name); at >= 0 && at < mine {
			return false
		}
	}
	return true
}

// peerQuestionMessages is the question as the model sees it. When the
// question is about the screen, the answer is grounded in a frame taken now:
// asked what was on its screen, a bot used to describe the QA report it
// imagined it was writing, because the prompt only gave it its task history
// and told it to ground every claim there. A question about what is visible
// deserves a look.
func (s *Server) peerQuestionMessages(ctx context.Context, inst protocol.Instance, msg protocol.PeerMessage) []connectors.Message {
	msgs := []connectors.Message{{
		Role: connectors.RoleUser,
		Text: msg.FromInstanceName + " asked: " + msg.Content,
	}}
	if !asksAboutScreen(msg.Content) || inst.State != protocol.InstanceRunning || inst.AgentdURL == "" {
		return msgs
	}
	octx, cancel := context.WithTimeout(ctx, 20*time.Second)
	defer cancel()
	obs, err := agent.NewSandboxClient(inst.AgentdURL).Observe(octx, agent.ObserveOptions{
		Screenshot: true, MaxWidth: 1024, Quality: 60,
	})
	if err != nil || obs == nil {
		return msgs
	}
	text := "This is your desktop right now. Active window: " + orDash(obs.ActiveWindow) +
		". Describe only what is actually visible in it."
	if obs.A11yTree != "" {
		text += "\nAccessibility tree:\n" + clipLine(obs.A11yTree, 1500)
	}
	msgs = append(msgs, connectors.Message{
		Role:      connectors.RoleUser,
		Text:      text,
		Image:     obs.ScreenshotB64,
		ImageMime: "image/webp",
	})
	return msgs
}

// asksAboutScreen is the cheap test for "is this about what you can see".
func asksAboutScreen(q string) bool {
	l := strings.ToLower(q)
	for _, k := range []string{"screen", "desktop", "window", "what do you see", "can you see", "showing", "display", "looking at", "open right now", "on your machine right now"} {
		if strings.Contains(l, k) {
			return true
		}
	}
	return false
}
